import type { HttpClient } from '../http/HttpClient.js';
import { mapPool } from '../util/pool.js';
import type { Account } from '../models/index.js';

/**
 * Autoconfiguração por espelhos (decisions D-16).
 *
 * Quando a URL configurada para de responder — provedor trocou de domínio, o
 * antigo caiu — o app busca uma lista de espelhos e procura um que atenda a
 * mesma conta.
 *
 * **A credencial do usuário é enviada em texto claro para cada candidato
 * testado.** Não há como evitar, e foram duas descobertas até chegar aqui:
 *
 * 1. medido no painel real, `player_api.php` devolve **404** tanto sem
 *    parâmetros quanto com credenciais falsas — não existe assinatura que
 *    identifique um painel Xtream sem mandar a senha de verdade;
 * 2. uma sondagem sem credencial é ainda pior no WebView: o painel só devolve
 *    cabeçalho CORS nas respostas da própria aplicação, então o 404 do nginx
 *    vem **sem** CORS e o navegador bloqueia. Toda sondagem falhava e todo
 *    servidor vivo parecia morto (visto no device: 44 candidatos sondados, zero
 *    aprovados, com espelhos que funcionavam na lista).
 *
 * Por isso é uma fase só — tentar autenticar direto — com concorrência baixa,
 * parando no primeiro acerto, e só com o usuário consentindo.
 */

export type FaseAutoConfig = 'lista' | 'login';

export interface ProgressoAutoConfig {
  fase: FaseAutoConfig;
  feitos: number;
  total: number;
  /** Candidato da vez, para a UI mostrar algo concreto. */
  url?: string;
}

export interface AutoConfigDeps {
  http: HttpClient;
  /** Onde buscar a lista de espelhos. */
  listUrl: string;
  /**
   * Autentica numa URL candidata. Fica fora daqui de propósito: quem monta o
   * provider com a credencial é a camada de cima, o núcleo não guarda senha.
   */
  autenticar: (serverUrl: string) => Promise<Account>;
  /** URL que falhou — vai para o fim da fila, já que acabou de não responder. */
  atual?: string;
  onProgress?: (p: ProgressoAutoConfig) => void;
  signal?: AbortSignal;
}

export interface ResultadoAutoConfig {
  serverUrl: string;
  account: Account;
}

/**
 * Quantos candidatos testar ao mesmo tempo.
 *
 * Baixo de propósito: cada tentativa expõe a credencial, então o paralelismo é
 * o mínimo que ainda torna a espera tolerável. Sequencial puro levaria minutos
 * numa lista de 45 endereços com domínios mortos que só falham por timeout.
 */
const TENTATIVAS_PARALELAS = 3;

/**
 * Procura um espelho que atenda a conta.
 * @returns a URL que funcionou, ou `null` se nenhuma serviu — nesse caso quem
 * chamou **não deve** mexer na configuração atual.
 */
export async function autoConfigurar(
  deps: AutoConfigDeps,
): Promise<ResultadoAutoConfig | null> {
  const { http, listUrl, autenticar, onProgress, signal } = deps;
  const avisar = (p: ProgressoAutoConfig) => onProgress?.(p);

  avisar({ fase: 'lista', feitos: 0, total: 1 });
  const candidatos = ordenar(await baixarLista(http, listUrl, signal), deps.atual);
  avisar({ fase: 'lista', feitos: 1, total: 1 });
  if (!candidatos.length) return null;

  let feitos = 0;
  let vencedor: { indice: number; resultado: ResultadoAutoConfig } | null = null;
  const achou = () => vencedor !== null || !!signal?.aborted;

  await mapPool(
    candidatos,
    TENTATIVAS_PARALELAS,
    async (serverUrl, indice) => {
      if (achou()) return;
      avisar({
        fase: 'login',
        feitos,
        total: candidatos.length,
        url: serverUrl,
      });
      try {
        const account = await autenticar(serverUrl);
        // pode haver mais de um acerto em voo: fica o mais alto na lista
        if (!vencedor || indice < vencedor.indice) {
          vencedor = { indice, resultado: { serverUrl, account } };
        }
      } catch {
        // candidato não serve (morto, não é painel, conta não existe ali):
        // seguir para o próximo é justamente o objetivo
      } finally {
        avisar({ fase: 'login', feitos: ++feitos, total: candidatos.length });
      }
    },
    { shouldStop: achou },
  );

  if (signal?.aborted) return null;
  return vencedor ? (vencedor as { resultado: ResultadoAutoConfig }).resultado : null;
}

/**
 * A URL que acabou de falhar vai para o fim — não some da fila porque a falha
 * pode ter sido passageira, mas é a última a ser tentada.
 */
function ordenar(urls: string[], atual?: string): string[] {
  if (!atual) return urls;
  const alvo = origemCanonica(atual);
  const outros = urls.filter((u) => origemCanonica(u) !== alvo);
  const mesma = urls.filter((u) => origemCanonica(u) === alvo);
  return [...outros, ...mesma];
}

/** Baixa e normaliza a lista de espelhos. */
async function baixarLista(
  http: HttpClient,
  listUrl: string,
  signal?: AbortSignal,
): Promise<string[]> {
  if (signal?.aborted) return [];
  const bruto = await http.json<unknown>(listUrl, { timeoutMs: 10_000, retries: 1 });
  const lista = Array.isArray(bruto)
    ? bruto
    : ((bruto as { endpoints?: unknown })?.endpoints ?? []);
  if (!Array.isArray(lista)) return [];

  // Dedupe por origem: a lista traz o mesmo host com e sem `:80` (medido: 59
  // entradas para 45 domínios), e testar duas vezes só gastaria tempo e exporia
  // a senha de novo.
  const vistos = new Set<string>();
  const out: string[] = [];
  for (const item of lista) {
    const url = normalizar(item);
    if (!url) continue;
    const chave = origemCanonica(url);
    if (vistos.has(chave)) continue;
    vistos.add(chave);
    out.push(url);
  }
  return out;
}

function normalizar(v: unknown): string | null {
  if (typeof v !== 'string') return null;
  const s = v.trim().replace(/\/+$/, '');
  if (!/^https?:\/\/[^/\s]+/i.test(s)) return null;
  return s;
}

/** `http://x.co:80` e `http://x.co` são o mesmo servidor. */
function origemCanonica(url: string): string {
  try {
    const u = new URL(url);
    const portaPadrao =
      (u.protocol === 'http:' && u.port === '80') ||
      (u.protocol === 'https:' && u.port === '443');
    return `${u.protocol}//${u.hostname}${portaPadrao || !u.port ? '' : `:${u.port}`}`;
  } catch {
    return url.toLowerCase();
  }
}

