import { useEffect, useRef, useState } from 'react';
import { setFocus } from '@noriginmedia/norigin-spatial-navigation';
import {
  HttpClient,
  XtreamProvider,
  autoConfigurar,
  type ProgressoAutoConfig,
  type StoredList,
} from '@mfp/core';
import { FocusButton } from '../components/FocusButton.js';
import { BalanceLoader } from '../components/BalanceLoader.js';
import { useRuntime } from '../runtime/RuntimeContext.js';
import { useLists } from '../state/lists.js';
import { t } from '../i18n/index.js';
import { gapColClass, gapRowClass, gapVar } from '../theme/gap.js';

/** Onde vive a lista de espelhos (decisions D-16). */
const LISTA_ESPELHOS = 'https://vitalsarcade.github.io/urls/list.json';

/**
 * Cliente dedicado à busca: curto e sem retentativa.
 *
 * O padrão do app (15s, 2 retentativas) faz sentido para o servidor do usuário,
 * mas aqui vira travamento — cada candidato morto custaria até 45s e a barra de
 * progresso ficava parada (visto no device: preso em "3 de 45"). Aqui a
 * pergunta é só "esse serve?", e a resposta certa para um morto é seguir logo.
 */
const CLIENTE_BUSCA = new HttpClient({ timeoutMs: 7000, retries: 0 });

export interface AutoConfigProps {
  list: StoredList;
  /** Deu certo: o servidor já foi trocado e a conta autenticada. */
  onSucesso: () => void;
  /** Desistiu ou nada funcionou — a configuração continua como estava. */
  onDesistir: () => void;
}

type Estado = 'perguntando' | 'rodando' | 'falhou';

/**
 * Autoconfiguração por espelhos (tela nova, decisions D-16).
 *
 * Aparece quando a URL configurada para de responder. Pergunta antes de rodar
 * porque testar um espelho **envia usuário e senha em texto claro** para ele —
 * não há como identificar um painel Xtream sem isso (medido: `player_api.php`
 * devolve 404 tanto sem parâmetros quanto com credenciais falsas).
 */
export function AutoConfig({ list, onSucesso, onDesistir }: Readonly<AutoConfigProps>) {
  const rt = useRuntime();
  const getPassword = useLists((s) => s.getPassword);
  const trocarServidor = useLists((s) => s.trocarServidor);
  const [estado, setEstado] = useState<Estado>('perguntando');
  const [progresso, setProgresso] = useState<ProgressoAutoConfig | null>(null);
  const abortar = useRef<AbortController | null>(null);

  useEffect(() => {
    setFocus(estado === 'rodando' ? 'auto-cancelar' : 'auto-sim');
  }, [estado]);

  useEffect(() => () => abortar.current?.abort(), []);

  const rodar = () => {
    setEstado('rodando');
    setProgresso(null);
    const ctrl = new AbortController();
    abortar.current = ctrl;

    void (async () => {
      const senha = await getPassword(rt, list.id);
      if (!senha) {
        setEstado('falhou');
        return;
      }
      const achado = await autoConfigurar({
        http: rt.http,
        listUrl: LISTA_ESPELHOS,
        atual: list.serverUrl,
        signal: ctrl.signal,
        onProgress: setProgresso,
        autenticar: (serverUrl) =>
          new XtreamProvider(
            {
              serverUrl,
              username: list.username,
              password: senha,
              ...(list.userAgent ? { userAgent: list.userAgent } : {}),
            },
            CLIENTE_BUSCA,
          ).authenticate(),
      }).catch(() => null);

      if (ctrl.signal.aborted) return;
      if (!achado) {
        // nada serviu: a configuração atual fica intacta, de propósito
        setEstado('falhou');
        return;
      }
      await trocarServidor(rt, list.id, achado.serverUrl);
      onSucesso();
    })();
  };

  const cancelar = () => {
    abortar.current?.abort();
    onDesistir();
  };

  return (
    <div
      style={{
        minHeight: '100%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '3vh 5vw',
        textAlign: 'center',
      }}
    >
      <div
        className={gapColClass}
        style={{ maxWidth: '38rem', display: 'flex', flexDirection: 'column', ...gapVar('1rem') }}
      >
        {estado === 'rodando' ? (
          <Rodando progresso={progresso} onCancelar={cancelar} />
        ) : (
          <Pergunta
            falhou={estado === 'falhou'}
            servidor={list.serverUrl}
            onSim={rodar}
            onNao={onDesistir}
          />
        )}
      </div>
    </div>
  );
}

function Pergunta({
  falhou,
  servidor,
  onSim,
  onNao,
}: Readonly<{ falhou: boolean; servidor: string; onSim: () => void; onNao: () => void }>) {
  return (
    <>
      <h2 style={{ margin: 0 }}>
        {falhou ? t('autoConfig.falhouTitulo') : t('autoConfig.titulo')}
      </h2>
      <p style={{ margin: 0, color: 'var(--text-secondary)' }}>
        {falhou ? t('autoConfig.falhouCorpo') : t('autoConfig.corpo', { servidor })}
      </p>
      {!falhou && (
        // o usuário precisa saber o que vai acontecer com a senha dele
        <p style={{ margin: 0, color: 'var(--text-disabled)', fontSize: 'var(--fs-meta)' }}>
          {t('autoConfig.aviso')}
        </p>
      )}
      <div
        className={gapRowClass}
        style={{ display: 'flex', justifyContent: 'center', ...gapVar('1rem') }}
      >
        <FocusButton primary focusKey="auto-sim" onPress={onSim}>
          {falhou ? t('autoConfig.tentarDeNovo') : t('autoConfig.procurar')}
        </FocusButton>
        <FocusButton focusKey="auto-nao" onPress={onNao}>
          {t('autoConfig.agoraNao')}
        </FocusButton>
      </div>
    </>
  );
}

function Rodando({
  progresso,
  onCancelar,
}: Readonly<{ progresso: ProgressoAutoConfig | null; onCancelar: () => void }>) {
  const fase = progresso?.fase ?? 'lista';
  const feitos = progresso?.feitos ?? 0;
  const total = progresso?.total ?? 1;
  const pct = total > 0 ? Math.min(100, Math.round((feitos / total) * 100)) : 0;

  const rotulo =
    fase === 'lista'
      ? t('autoConfig.faseLista')
      : t('autoConfig.faseLogin', { feitos: Math.min(feitos + 1, total), total });

  return (
    <>
      <BalanceLoader />
      <h2 style={{ margin: 0 }}>{t('autoConfig.procurando')}</h2>
      <p style={{ margin: 0, color: 'var(--text-secondary)' }}>{rotulo}</p>

      <div
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={pct}
        style={{
          height: '0.6rem',
          borderRadius: 999,
          background: 'var(--bg-raised)',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            width: `${pct}%`,
            height: '100%',
            background: 'var(--accent)',
            transition: 'width var(--dur-base) var(--ease)',
          }}
        />
      </div>

      {/* o candidato da vez, para não parecer travado numa lista longa */}
      <p
        style={{
          margin: 0,
          minHeight: '1.4em',
          color: 'var(--text-disabled)',
          fontSize: 'var(--fs-meta)',
          overflowWrap: 'anywhere',
        }}
      >
        {progresso?.url ?? ''}
      </p>

      <FocusButton focusKey="auto-cancelar" onPress={onCancelar}>
        {t('common.cancel')}
      </FocusButton>
    </>
  );
}
